    /**
     * Keys adopted into file + shard.
     */
    public var written: UInt64
    /**
     * Values regenerated that were human-owned (`include_human` tier).
     */
    public var regeneratedHuman: UInt64
    /**
     * Shard entries pruned (key gone from source and target).
     */
    public var pruned: UInt64
    public var adoptedHuman: UInt64
    public var reconciledHuman: UInt64
    /**
     * Scoped keys with an existing AI-owned value left alone.
     */
    public var skippedExisting: UInt64
    /**
     * Same set, human-owned subset.
     */
    public var skippedHuman: UInt64
    /**
     * In-chunk keys the provider omitted from its response.
     */
    public var omitted: [String]
    /**
     * Existing values destroyed by a write (leaf/shape replacement).
     */
    public var clobbered: [String]
    /**
     * Keys sent through a corrective round by the validation gate.
     */
    public var refilled: UInt64
    /**
     * Gate findings still open after the last corrective round; the
     * values were adopted anyway and live on the shard entry's
     * `quality.unresolved`.
     */
    public var unresolved: [CheckFinding]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(requested: UInt64, 
        /**
         * Provider answered for an in-chunk key.
         */translated: UInt64, 
        /**
         * Keys adopted into file + shard.
         */written: UInt64, 
        /**
         * Values regenerated that were human-owned (`include_human` tier).
         */regeneratedHuman: UInt64, 
        /**
         * Shard entries pruned (key gone from source and target).
         */pruned: UInt64, adoptedHuman: UInt64, reconciledHuman: UInt64, 
        /**
         * Scoped keys with an existing AI-owned value left alone.
         */skippedExisting: UInt64, 
        /**
         * Same set, human-owned subset.
         */skippedHuman: UInt64, 
        /**
         * In-chunk keys the provider omitted from its response.
         */omitted: [String], 
        /**
         * Existing values destroyed by a write (leaf/shape replacement).
         */clobbered: [String], 
        /**
         * Keys sent through a corrective round by the validation gate.
         */refilled: UInt64, 
        /**
         * Gate findings still open after the last corrective round; the
         * values were adopted anyway and live on the shard entry's
         * `quality.unresolved`.
         */unresolved: [CheckFinding]) {
        self.requested = requested
        self.translated = translated
        self.written = written
        self.regeneratedHuman = regeneratedHuman
        self.pruned = pruned
        self.adoptedHuman = adoptedHuman
        self.reconciledHuman = reconciledHuman
        self.skippedExisting = skippedExisting
        self.skippedHuman = skippedHuman
        self.omitted = omitted
        self.clobbered = clobbered
        self.refilled = refilled
        self.unresolved = unresolved
    }

    

    
}

