    typealias SwiftType = IntlAiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> IntlAiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Config(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .Lockfile(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .Io(
            try FfiConverterString.read(from: &buf)
            )
        case 4: return .Format(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .Transport(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .Validation(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .Other(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: IntlAiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Config(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Lockfile(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Io(v1):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Format(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Transport(v1):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Validation(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Other(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


